			templ_7745c5c3_Err = templruntime.WriteString(templ_7745c5c3_Buffer, 57, "\"> <label class=\"block\"><span class=\"mb-1.5 block text-[13px] font-medium text-text-2\">Crédits</span> <input type=\"number\" name=\"credits\" min=\"1\" required class=\"h-[38px] w-[140px] rounded-lg border border-line px-3 font-mono text-sm outline-none focus:border-brand\"></label> <label class=\"block\"><span class=\"mb-1.5 block text-[13px] font-medium text-text-2\">Prix (€) <span class=\"font-normal text-text-4\">— facultatif</span></span> <input type=\"number\" name=\"price_eur\" min=\"0\" step=\"0.01\" placeholder=\"auto\" class=\"h-[38px] w-[120px] rounded-lg border border-line px-3 font-mono text-sm outline-none focus:border-brand\"></label> <button type=\"submit\" class=\"h-[38px] shrink-0 whitespace-nowrap rounded-lg bg-brand px-4 text-sm font-semibold text-white hover:bg-brand-strong\">Ajouter l'offre</button><div class=\"w-full text-[13px] text-text-4\">Laissé vide, le prix découle du coût réel et de la marge visée, arrondi à l'euro supérieur. <output name=\"suggestion\" class=\"font-medium text-text-2\"></output></div></form><!-- Aperçu du prix pendant la saisie. Le calcul qui fait foi\n\t\t\t\t\t     reste celui du serveur : ce script ne fait que montrer\n\t\t\t\t\t     à l'avance ce qu'il produira. --><script>\n\t\t\t\t\t\t(function () {\n\t\t\t\t\t\t\tvar form = document.currentScript.previousElementSibling;\n\t\t\t\t\t\t\tif (!form) return;\n\t\t\t\t\t\t\tvar cost = parseFloat(form.dataset.creditCost || \"0\");\n\t\t\t\t\t\t\tvar margin = parseFloat(form.dataset.targetMargin || \"0\");\n\t\t\t\t\t\t\tvar credits = form.elements[\"credits\"];\n\t\t\t\t\t\t\tvar price = form.elements[\"price_eur\"];\n\t\t\t\t\t\t\tvar out = form.querySelector(\"output[name=suggestion]\");\n\t\t\t\t\t\t\tfunction refresh() {\n\t\t\t\t\t\t\t\tvar n = parseInt(credits.value, 10);\n\t\t\t\t\t\t\t\tif (!n || n <= 0 || !cost || margin < 0 || margin >= 100) {\n\t\t\t\t\t\t\t\t\tout.textContent = \"\";\n\t\t\t\t\t\t\t\t\treturn;\n\t\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\t\tvar suggested = Math.max(1, Math.ceil(n * cost / (1 - margin / 100)));\n\t\t\t\t\t\t\t\tout.textContent = price.value ? \"\" : \" Prix calculé : \" + suggested + \" €.\";\n\t\t\t\t\t\t\t}\n\t\t\t\t\t\t\tcredits.addEventListener(\"input\", refresh);\n\t\t\t\t\t\t\tprice.addEventListener(\"input\", refresh);\n\t\t\t\t\t\t})();\n\t\t\t\t\t</script></div><form method=\"post\" action=\"/admin/pricing/settings\" class=\"w-full shrink-0 lg:w-[360px] rounded-[11px] border border-line-2 bg-white p-5.5\"><input type=\"hidden\" name=\"csrf_token\" value=\"")
